package com.careerpilot.modules.assessment.service;

import com.careerpilot.exception.*;import com.careerpilot.modules.assessment.dto.*;import com.careerpilot.modules.assessment.entity.*;import com.careerpilot.modules.assessment.grading.AssessmentGradingService;import com.careerpilot.modules.assessment.mapper.AssessmentMapper;import com.careerpilot.modules.assessment.repository.*;import com.careerpilot.modules.auth.entity.User;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service
public class AssessmentService{
 private static final UUID FULL_PLACEMENT_MOCK=UUID.fromString("20000000-0000-0000-0000-000000000005");
 private static final Map<String,Integer>FULL_PLACEMENT_QUOTAS=Map.of("APTITUDE",4,"LOGICAL",3,"PROGRAMMING",3,"DSA",3,"DBMS_SQL",2,"CS_FUNDAMENTALS",2,"DEBUGGING",2,"BACKEND",1);
 private final AssessmentRepository assessments;private final AssessmentAttemptRepository attempts;private final AssessmentMapper mapper;private final AssessmentGradingService grading;
 public AssessmentService(AssessmentRepository assessments,AssessmentAttemptRepository attempts,AssessmentMapper mapper,AssessmentGradingService grading){this.assessments=assessments;this.attempts=attempts;this.mapper=mapper;this.grading=grading;}
 @Transactional(readOnly=true)public List<AssessmentSummaryResponse>catalog(){return assessments.findByActiveTrueOrderByTitle().stream().map(mapper::summary).toList();}
 @Transactional(readOnly=true)public AssessmentDetailResponse detail(UUID id){return mapper.detail(loadAssessment(id));}
 @Transactional public AttemptResponse start(User user,UUID assessmentId){Assessment assessment=loadAssessment(assessmentId);List<AssessmentQuestion>selectedQuestions=selectQuestions(assessment);AssessmentAttempt attempt=new AssessmentAttempt();attempt.setAssessment(assessment);attempt.setUser(user);attempt.setStatus(AttemptStatus.IN_PROGRESS);attempt.setTotalQuestions(selectedQuestions.size());for(int i=0;i<selectedQuestions.size();i++){AssessmentAttemptQuestion selected=new AssessmentAttemptQuestion();selected.setAttempt(attempt);selected.setQuestion(selectedQuestions.get(i));selected.setQuestionOrder(i+1);attempt.getSelectedQuestions().add(selected);}return mapper.attempt(attempts.save(attempt));}
 @Transactional public AttemptResponse get(User user,UUID id){AssessmentAttempt attempt=owned(user,id);expireIfNeeded(attempt,Instant.now());return mapper.attempt(attempt);}
 @Transactional public AttemptResponse submit(User user,UUID id,SubmitAttemptRequest request){AssessmentAttempt attempt=owned(user,id);if(attempt.getStatus()!=AttemptStatus.IN_PROGRESS)throw new ConflictException("Only an in-progress attempt can be submitted");Instant now=Instant.now();if(isExpired(attempt,now)){attempt.setStatus(AttemptStatus.EXPIRED);attempts.save(attempt);throw new ConflictException("Assessment attempt has expired");}grading.grade(attempt,request.answers(),now);return mapper.attempt(attempts.save(attempt));}
 @Transactional public List<AttemptSummaryResponse>history(User user){return attempts.findByUserIdOrderByCreatedAtDesc(user.getId()).stream().peek(v->expireIfNeeded(v,Instant.now())).map(mapper::attemptSummary).toList();}
 @Transactional public AttemptSummaryResponse latest(User user){return attempts.findFirstByUserIdAndStatusOrderByCreatedAtDesc(user.getId(),AttemptStatus.SUBMITTED).map(mapper::attemptSummary).orElse(null);}
 private Assessment loadAssessment(UUID id){return assessments.findWithQuestionsByIdAndActiveTrue(id).orElseThrow(()->new NotFoundException("Assessment not found"));}
 private AssessmentAttempt owned(User user,UUID id){AssessmentAttempt attempt=attempts.findByIdAndUserId(id,user.getId()).orElseThrow(()->new NotFoundException("Assessment attempt not found"));attempt.getAssessment().getQuestions().forEach(q->q.getOptions().size());attempt.getSelectedQuestions().forEach(v->{v.getQuestion().getId();v.getQuestion().getOptions().size();});attempt.getAnswers().forEach(a->a.getQuestion().getId());return attempt;}
 private void expireIfNeeded(AssessmentAttempt attempt,Instant now){if(attempt.getStatus()==AttemptStatus.IN_PROGRESS&&isExpired(attempt,now)){attempt.setStatus(AttemptStatus.EXPIRED);attempts.save(attempt);}}
 private boolean isExpired(AssessmentAttempt attempt,Instant now){return !now.isBefore(attempt.getStartedAt().plusSeconds(attempt.getAssessment().getDurationMinutes()*60L));}
 private List<AssessmentQuestion>selectQuestions(Assessment assessment){if(!FULL_PLACEMENT_MOCK.equals(assessment.getId())){List<AssessmentQuestion>bank=new ArrayList<>(assessment.getQuestions());Collections.shuffle(bank);return List.copyOf(bank.subList(0,Math.min(assessment.getTotalQuestions(),bank.size())));}List<AssessmentQuestion>selected=new ArrayList<>();for(var quota:FULL_PLACEMENT_QUOTAS.entrySet()){List<AssessmentQuestion>category=assessment.getQuestions().stream().filter(q->quota.getKey().equals(q.getSelectionCategory())).collect(java.util.stream.Collectors.toCollection(ArrayList::new));if(category.size()<quota.getValue())throw new IllegalStateException("Full placement mock bank is missing category "+quota.getKey());Collections.shuffle(category);selected.addAll(category.subList(0,quota.getValue()));}Collections.shuffle(selected);return List.copyOf(selected);}
}
